n_name": "黎阳、顿丘、杨村、滑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e5ccfbb8-0dcd-562a-b315-fff62d319829"}, {"title": "李存进以苇笮系巨舰，于德胜逾月造浮梁", "start_year": 919, "end_year": 919, "time_original": "919年八月后本段；历时逾月，确日未载", "dynasty": "五代十国", "description": "李存进以苇笮系巨舰，于德胜逾月造浮梁。", "phases": [], "location_name": "德胜", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4c4f6d35-7d0a-5c57-ab79-42aa57cd148c"}, {"title": "徐温奉吴王书归还无锡之俘，钱镠遣使请和", "start_year": 919, "end_year": 919, "time_original": "919年无锡战后本段；确日未载", "dynasty": "五代十国", "description": "徐温奉吴王书归还无锡之俘，钱镠遣使请和。", "phases": [], "location_name": "吴、吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3de4d80f-44c1-5a80-9a0e-2e55322fe230"}, {"title": "吴与吴越议和后，史书追述吴地长期休兵", "start_year": null, "end_year": null, "time_original": "自919年本段以后约二十余年；非919年单年结果", "dynasty": "五代十国", "description": "吴与吴越议和后，史书追述吴地长期休兵。", "phases": [], "location_name": "吴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "786a7758-c115-561e-8755-90366a809532"}, {"title": "吴王与徐温屡致书劝钱镠自王，钱镠不从", "start_year": null, "end_year": null, "time_original": "919年后屡次；具体年月未载", "dynasty": "五代十国", "description": "吴王与徐温屡致书劝钱镠自王，钱镠不从。", "phases": [], "location_name": "吴、吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "150e5845-90ab-511f-a6c9-2c131aceae9a"}, {"title": "梁廷九月丙寅削刘岩官爵并命钱镠讨之", "start_year": 919, "end_year": 919, "time_original": "919年九月丙寅", "dynasty": "五代十国", "description": "梁廷九月丙寅削刘岩官爵并命钱镠讨之。", "phases": [], "location_name": "梁、广州、吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f0eca826-d523-5d77-81b5-2a76aa02237f"}, {"title": "钱镠虽受梁命，最终未攻刘岩", "start_year": 919, "end_year": 919, "time_original": "919年九月诏命后；未行的观察期限未载", "dynasty": "五代十国", "description": "钱镠虽受梁命，最终未攻刘岩。", "phases": [], "location_name": "吴越、广州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "64e21d8e-8758-5718-a050-84f6d641665c"}, {"title": "吴庐江公杨濛感叹国家为他人所有，徐温闻而恶之", "start_year": 919, "end_year": 919, "time_original": "919年本段概述；言论次数和确日未载", "dynasty": "五代十国", "description": "吴庐江公杨濛感叹国家为他人所有，徐温闻而恶之。", "phases": [], "location_name": "吴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "11d74245-9426-53fb-9b48-5a79fbabe606"}]'::jsonb)
